def transform(grid):
    height, width = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    components_by_color = {}

    for color in set(value for row in grid for value in row) - {background}:
        seen = set()
        components = []
        for r in range(height):
            for c in range(width):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                queue = [(r, c)]
                seen.add((r, c))
                component = []
                for y, x in queue:
                    component.append((y, x))
                    for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                        if (0 <= ny < height and 0 <= nx < width and
                                grid[ny][nx] == color and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            queue.append((ny, nx))
                components.append(component)
        components_by_color[color] = components

    retained = {}
    for color, components in components_by_color.items():
        for component in components:
            rows = [r for r, _ in component]
            cols = [c for _, c in component]
            area = (max(rows) - min(rows) + 1) * (max(cols) - min(cols) + 1)
            if area < 4 or len(component) / area < 0.70:
                break
        else:
            retained[color] = components

    output = [[background] * width for _ in range(height)]
    for color, components in retained.items():
        for component in components:
            r0 = min(r for r, _ in component)
            r1 = max(r for r, _ in component)
            c0 = min(c for _, c in component)
            c1 = max(c for _, c in component)
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    output[r][c] = color
    return output
